import{z as s,x as i,o as E,c as d,q as m,j as o,D as e,d as l,s as p,S as A,b as r}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"TP 通信重叠","description":"","frontmatter":{"title":"TP 通信重叠","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/tp-comm-overlap.md","filePath":"llm/tp-comm-overlap.md","lastUpdated":1791413859000}'),B={name:"llm/tp-comm-overlap.md"};function n(c,a,C,h,_,T){const t=i("Mermaid");return E(),d("div",null,[a[2]||(a[2]=m('<h1 id="tp-通信重叠" tabindex="-1">TP 通信重叠 <a class="header-anchor" href="#tp-通信重叠" aria-label="Permalink to &quot;TP 通信重叠&quot;">​</a></h1><div class="epigraph"><p>层内 All-Reduce 与下一层的 GEMM 在数据依赖上不是铁板一块：切对流水，通信可以躲进计算的阴影里。</p><footer>—— Shoeybi 等 Megatron-LM 的切分使非线性局部化；推理引擎把短 AR 与下一层投影重叠</footer></div><p><a href="/llm/custom-allreduce">上一课</a>把短 All-Reduce 的路径选好。本课问墙钟能不能 <em>藏</em> 掉它。训练里通信重叠是老问题；decode 每层计算很瘦，阴影浅，重叠更难、也更值钱。依赖链是：行并行 GEMM 产出部分和 → AR → 下一层需要完整向量。若下一层能先做不依赖完整向量的工作（比如已经列切、只需要本地 KV 的注意力），就可以错开。切错则 AR 成为硬屏障。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>逐步时间 \\(\\approx T_{\\mathrm{cmp}}+T_{\\mathrm{comm}}\\) 若串行。重叠后 \\(\\approx \\max(T_{\\mathrm{cmp}},T_{\\mathrm{comm}})+\\) 无法隐藏的暴露通信。decode 上 \\(T_{\\mathrm{cmp}}\\) 小，能藏的通信有限；prefill 上 \\(T_{\\mathrm{cmp}}\\) 大，AR 更容易藏。缺口是按阶段决定要不要为重叠改切分与流（CUDA stream），而不是处处套训练的 overlap 模板。</p><p>投机校验让一层的查询变宽，\\(T_{\\mathrm{cmp}}\\) 上升，重叠窗口变大——加速比不只来自少步，也来自更好藏通信。</p><p><span class="marginnote">暴露通信是无法与任何本地计算并行的那一段：依赖尚未满足。流水图画错会把「已重叠」写进文档，profiler 上 NCCL/自定义 AR 仍与 GEMM 串行。</span></p><p><span class="marginnote">数字实例：设一次 decode 步计算 2 ms、每层 All-Reduce 0.5 ms、共 80 层——串行时约 42 ms 墙钟，通信贡献 40 ms；重叠的下界是 \\(\\max(T_{\\mathrm{cmp}},T_{\\mathrm{comm}})\\approx 40\\) ms——通信远长于计算时，能重叠掉的至多是那 2 ms 串行段，40 ms 的通信本体仍要自己走完。decode 上 \\(T_{\\mathrm{cmp}}\\) 小、阴影浅，通常连这一段都藏不满，但藏下的每一毫秒都直接写进逐步延迟。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>注意力：头在本地，softmax 不通信；输出投影行并行后 AR。MLP：列切上投影本地非线性，下投影后 AR。重叠点：上一层 AR 与下一层 QKV 或上投影的本地部分。实现用双流：计算流与通信流，事件同步。CUDA Graph 要包含两流，否则捕获后重叠消失。自定义 AR 的持久工作组必须能在通信流上跑。</p><p>测：Nsight 上看 AR 与 GEMM 的时间条是否交叠。只看逐步毫秒会把重叠与更快的 AR 混在一起。</p><p><span class="marginnote">「双流 + 事件同步」就是开两条 GPU 任务队列：一条跑计算、一条跑通信，平时互不等待；只在真正依赖对方结果的地方插一个「事件」当路障。类比厨房里炒菜（计算）与传菜（通信）两条线并行，只在端盘前确认菜已出锅。</span></p>',12)),(E(),o(A,null,{default:e(()=>[p(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20GEMM1%5B%22%E8%A1%8C%E5%B9%B6%E8%A1%8C%20GEMM%22%5D%20--%3E%20AR%5B%22All-Reduce%22%5D%0A%20%20GEMM1%20--%3E%20LOC%5B%22%E4%B8%8B%E4%B8%80%E5%B1%82%E6%9C%AC%E5%9C%B0%E5%8F%AF%E5%81%9A%E9%83%A8%E5%88%86%22%5D%0A%20%20AR%20--%3E%20BAR%5B%22%E9%9C%80%E8%A6%81%E5%AE%8C%E6%95%B4%E5%90%91%E9%87%8F%E7%9A%84%E9%83%A8%E5%88%86%22%5D%0A%20%20LOC%20--%3E%20BAR%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[l("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,"数学依赖不能违背：残差加若需要完整 \\(Y\\)，AR 之后才能加。有的实现把残差放进融合核，通信必须先完成。为重叠而拆融合，可能得不偿失——decode 上融合省的 HBM 可能大于重叠省的暴露通信。应用 profiler 决定，不要按训练论文的百分比抄。",-1)),(E(),o(A,null,{default:e(()=>[p(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20STEP%5B%22%E4%B8%80%E4%B8%AA%20decode%20%E6%AD%A5%E7%9A%84%E5%A2%99%E9%92%9F%22%5D%20--%3E%20Q%7B%22%E9%80%9A%E4%BF%A1%E4%B8%8E%E8%AE%A1%E7%AE%97%E6%80%8E%E4%B9%88%E6%8E%92%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22%E4%B8%B2%E8%A1%8C%EF%BC%9A%E7%AE%97%E5%AE%8C%E5%86%8D%E4%BC%A0%22%7C%20SER%5B%22%E6%97%B6%E9%97%B4%E8%BF%91%E4%BC%BC%20T_cmp%20%2B%20T_comm%22%5D%0A%20%20Q%20--%3E%7C%22%E5%8F%8C%E6%B5%81%E9%87%8D%E5%8F%A0%22%7C%20OV%5B%22%E6%97%B6%E9%97%B4%E8%BF%91%E4%BC%BC%20max(T_cmp%2C%20T_comm)%20%E5%8A%A0%E6%9A%B4%E9%9C%B2%E6%AE%B5%22%5D%0A%20%20SER%20--%3E%20SLOW%5B%22decode%20%E4%B8%8A%20T_cmp%20%E5%B0%8F%EF%BC%8C%E4%B8%B2%E8%A1%8C%E4%BA%8F%E5%BE%97%E5%A4%9A%22%5D%0A%20%20OV%20--%3E%20HIDE%5B%22AR%20%E8%97%8F%E8%BF%9B%E4%B8%8B%E4%B8%80%E5%B1%82%E6%9C%AC%E5%9C%B0%20GEMM%20%E7%9A%84%E9%98%B4%E5%BD%B1%E9%87%8C%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=m('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>跨节点 TP 的 AR 更长，更值得重叠，但也更难与自定义路径结合。MoE 的 all-to-all 是另一类通信，不要与稠密 TP 的 AR 重叠策略混写。下一课：还在用 NCCL 时，有哪些旋钮。</p><p><span class="marginnote">常见误区：把「配置里开了 overlap」当成通信已被藏住。若 CUDA Graph 捕获时漏掉通信流，或融合核里塞了需要完整 \\(Y\\) 的残差加，profiler 上 AR 与 GEMM 仍然首尾相接。验收只能看时间条是否交叠，不能看配置布尔。</span></p><p>出处：Megatron-LM；NVIDIA 对 Transformer 引擎通信重叠的工程说明。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>重叠把逐步时间从和变成近似 max；decode 阴影浅。</li><li>切分必须留下「AR 未完成也能做」的本地工作。</li><li>双流 + 事件；CUDA Graph 要含通信流。</li><li>拆融合换重叠未必赢，用 trace 决定。</li><li>prefill / 投机宽查询更好藏。</li><li>下一课：NCCL 调优。</li><li>出处：Shoeybi et al., Megatron-LM。</li></ul>',6))])}const M=s(B,[["render",n]]);export{u as __pageData,M as default};
